/// The default client. It sends each request through the proxy the environment names for its
/// scheme, as curl does: `HTTPS_PROXY`, `HTTP_PROXY` or `ALL_PROXY`, unless `NO_PROXY` matches
/// its host. Lowercase names work too; `HTTP_PROXY` is ignored in a CGI script.
pub(crate) fn default_client() -> Arc<dyn HttpClient> {
    let direct = http_client(crate::make_connector());
    let var = |names: &[&str]| {
        names
            .iter()
            .find_map(|name| std::env::var(name).ok().filter(|value| !value.trim().is_empty()))
    };
    let all = var(&["ALL_PROXY", "all_proxy"]);
    let cgi = std::env::var_os("REQUEST_METHOD").is_some();
    let http = var(if cgi { &["http_proxy"] } else { &["HTTP_PROXY", "http_proxy"] });
    let https = var(&["HTTPS_PROXY", "https_proxy"]).or_else(|| all.clone());
    let http = http.or(all).as_deref().and_then(Proxy::parse).map(|p| p.route(false));
    let https = https.as_deref().and_then(Proxy::parse).map(|p| p.route(true));
    if http.is_none() && https.is_none() {
        return direct;
    }
    Arc::new(ProxyClient {
        direct,
        http,
        https,
        no_proxy: NoProxy::parse(&var(&["NO_PROXY", "no_proxy"]).unwrap_or_default()),
    })
}

struct ProxyClient {
    direct: Arc<dyn HttpClient>,
    http: Option<Route>,
    https: Option<Route>,
    no_proxy: NoProxy,
}

enum Route {
    /// HTTPS through a CONNECT tunnel, or anything through SOCKS5.
    Client(Arc<dyn HttpClient>),
    /// Plain HTTP sent to the proxy, with the absolute URL.
    Forward(Proxy),
    Unsupported(String),
}

impl HttpClient for ProxyClient {
    fn send(
        &self,
        request: http::Request<RequestBody>,
    ) -> BoxFuture<'_, Result<http::Response<Incoming>, BoxError>> {
        let uri = request.uri();
        let route = match uri.scheme_str() {
            _ if uri.host().is_none_or(|host| self.no_proxy.matches(host)) => None,
            Some("https") => self.https.as_ref(),
            Some("http") => self.http.as_ref(),
            _ => None,
        };
        match route {
            None => self.direct.send(request),
            Some(Route::Client(client)) => client.send(request),
            Some(Route::Forward(proxy)) => Box::pin(forward(proxy, request)),
            Some(Route::Unsupported(message)) => {
                let error = BoxError::from(message.clone());
                Box::pin(async move { Err(error) })
            }
        }
    }
}

/// Sends `request` over a new connection to an HTTP proxy.
async fn forward(
    proxy: &Proxy,
    mut request: http::Request<RequestBody>,
) -> Result<http::Response<Incoming>, BoxError> {
    let stream = tokio::net::TcpStream::connect(proxy.address()).await?;
    let (mut sender, connection) =
        hyper::client::conn::http1::handshake(TokioIo::new(stream)).await?;
    TokioExecutor::new().execute(async move {
        let _ = connection.await;
    });
    let host = request.uri().authority().map(|authority| {
        let host = authority.as_str();
        HeaderValue::from_str(host.rsplit('@').next().unwrap_or(host))
    });
    if let Some(host) = host.transpose()? {
        request.headers_mut().entry(HOST).or_insert(host);
    }
    if let Some(auth) = proxy.authorization() {
        request.headers_mut().insert(PROXY_AUTHORIZATION, auth);
    }
    Ok(sender.send_request(request).await?)
}

#[derive(Debug, PartialEq, Eq)]
struct Proxy {
    /// `http`, `https`, `socks5` or `socks5h`: a URL without one is `http`.
    scheme: String,
    host: String,
    port: u16,
    credentials: Option<(String, String)>,
}

impl Proxy {
    fn parse(value: &str) -> Option<Self> {
        let value = value.trim();
        let url = if value.contains("://") {
            url::Url::parse(value)
        } else {
            url::Url::parse(&format!("http://{value}"))
        }
        .ok()?;
        let decode = |text: &str| {
            percent_encoding::percent_decode_str(text)
                .decode_utf8_lossy()
                .into_owned()
        };
        let credentials = (!url.username().is_empty())
            .then(|| (decode(url.username()), decode(url.password().unwrap_or_default())));
        Some(Self {
            scheme: url.scheme().to_owned(),
            host: url.host_str().filter(|host| !host.is_empty())?.to_owned(),
            port: url.port_or_known_default().unwrap_or(1080),
            credentials,
        })
    }

    fn address(&self) -> String {
        format!("{}:{}", self.host, self.port)
    }

    fn authorization(&self) -> Option<HeaderValue> {
        let (user, password) = self.credentials.as_ref()?;
        let credentials = base64(format!("{user}:{password}").as_bytes());
        let mut value = HeaderValue::try_from(format!("Basic {credentials}")).ok()?;
        value.set_sensitive(true);
        Some(value)
    }

    fn route(self, https: bool) -> Route {
        let uri = Uri::builder()
            .scheme(self.scheme.as_str())
            .authority(self.address())
            .path_and_query("/")
            .build();
        let uri = match uri {
            Ok(uri) => uri,
            Err(error) => return Route::Unsupported(format!("invalid proxy URL: {error}")),
        };
        match self.scheme.as_str() {
            "socks5" | "socks5h" => {
                let mut socks = SocksV5::new(uri, http()).local_dns(self.scheme == "socks5");
                if let Some((user, password)) = self.credentials {
                    socks = socks.with_auth(user, password);
                }
                Route::Client(http_client(tls(socks)))
            }
            "http" | "https" if https => {
                let mut tunnel = Tunnel::new(uri, crate::make_connector());
                if let Some(auth) = self.authorization() {
                    tunnel = tunnel.with_auth(auth);
                }
                Route::Client(http_client(tls(tunnel)))
            }
            "http" => Route::Forward(self),
            scheme => Route::Unsupported(format!(
                "{scheme} proxies are not supported for {} requests",
                if https { "https" } else { "http" }
            )),
        }
    }
}

/// `NO_PROXY`: `*`, IP addresses and networks, and domains, which match their subdomains too.
#[derive(Debug, Default)]
struct NoProxy(Vec<String>);

impl NoProxy {
    fn parse(value: &str) -> Self {
        let entries = value.split(',').map(|entry| entry.trim().to_ascii_lowercase());
        Self(entries.filter(|entry| !entry.is_empty()).collect())
    }

    fn matches(&self, host: &str) -> bool {
        let host = host.trim_start_matches('[').trim_end_matches(']').to_ascii_lowercase();
        let host = host.trim_end_matches('.');
        let ip = host.parse::<IpAddr>().ok();
        self.0.iter().any(|entry| match ip {
            _ if entry == "*" => true,
            Some(ip) => in_network(entry, ip),
            None => {
                let domain = entry.trim_start_matches('*').trim_start_matches('.');
                host.strip_suffix(domain)
                    .is_some_and(|sub| sub.is_empty() || sub.ends_with('.'))
            }
        })
    }
}

fn in_network(entry: &str, ip: IpAddr) -> bool {
    let (address, bits) = entry.split_once('/').unwrap_or((entry, ""));
    let address = address.trim_start_matches('[').trim_end_matches(']');
    let (network, ip, width) = match (address.parse::<IpAddr>(), ip) {
        (Ok(IpAddr::V4(network)), IpAddr::V4(ip)) => {
            (u32::from(network).into(), u32::from(ip).into(), 32)
        }
        (Ok(IpAddr::V6(network)), IpAddr::V6(ip)) => (u128::from(network), u128::from(ip), 128),
        _ => return false,
    };
    let bits = if bits.is_empty() { Ok(width) } else { bits.parse::<u32>() };
    bits.is_ok_and(|bits| {
        bits <= width && (network ^ ip).checked_shr(width - bits).unwrap_or(0) == 0
    })
}

fn http() -> HttpConnector {
    let mut http = HttpConnector::new();
    http.enforce_http(false);
    http
}

