/// Trusts the platform's roots. Without any, requests fail with a TLS error rather than
/// the client panicking on creation.
#[cfg(feature = "rustls-tls")]
fn tls<C>(connector: C) -> hyper_rustls::HttpsConnector<C> {
    let provider = rustls::crypto::CryptoProvider::get_default()
        .cloned()
        .unwrap_or_else(|| Arc::new(rustls::crypto::ring::default_provider()));
    let builder = hyper_rustls::HttpsConnectorBuilder::new();
    let builder = match builder.with_provider_and_native_roots(provider.clone()) {
        Ok(builder) => builder,
        Err(_) => hyper_rustls::HttpsConnectorBuilder::new().with_tls_config(
            rustls::ClientConfig::builder_with_provider(provider)
                .with_safe_default_protocol_versions()
                .expect("the default provider supports the default protocol versions")
                .with_root_certificates(rustls::RootCertStore::empty())
                .with_no_client_auth(),
        ),
    };
    let builder = builder.https_or_http();
    #[cfg(feature = "http1")]
    let builder = builder.enable_http1();
    #[cfg(feature = "http2")]
    let builder = builder.enable_http2();
    builder.wrap_connector(connector)
}

#[cfg(test)]
mod tests {
    use super::{NoProxy, Proxy};

    #[test]
    fn proxy_urls_default_to_http_and_decode_credentials() {
        let proxy = Proxy::parse("user%40corp:p%3Ass@proxy.corp:3128").unwrap();
        assert_eq!(proxy.scheme, "http");
        assert_eq!(proxy.address(), "proxy.corp:3128");
        assert_eq!(proxy.credentials, Some(("user@corp".into(), "p:ss".into())));
        assert_eq!(proxy.authorization().unwrap(), "Basic dXNlckBjb3JwOnA6c3M=");
        assert_eq!(Proxy::parse("http://proxy.corp").unwrap().port, 80);
        assert_eq!(Proxy::parse("socks5h://[::1]").unwrap().address(), "[::1]:1080");
        assert!(Proxy::parse("http://").is_none());
    }

    #[test]
    fn no_proxy_matches_domains_their_subdomains_and_networks() {
        let no_proxy = NoProxy::parse(" Example.com, .internal ,*.svc, 10.0.0.0/8, ::1, 192.168.1.7");
        let bypassed = ["example.com", "api.example.com", "EXAMPLE.COM.", "a.b.internal", "x.svc"];
        for host in bypassed.into_iter().chain(["10.1.2.3", "[::1]", "192.168.1.7"]) {
            assert!(no_proxy.matches(host), "{host}");
        }
        let proxied = ["notexample.com", "example.org", "internal.org", "11.0.0.1", "192.168.1.8"];
        for host in proxied.into_iter().chain(["[::2]"]) {
            assert!(!no_proxy.matches(host), "{host}");
        }
        assert!(NoProxy::parse("*").matches("anything.example"));
        assert!(!NoProxy::parse("").matches("example.com"));
        assert!(NoProxy::parse("0.0.0.0/0").matches("8.8.8.8"));
    }
}
